// Offline 14.24 anvils. Copyrighted inputs and every generated byte stay in assets3d-local.
import { createReadStream } from 'node:fs';
import { readFile, mkdir, mkdtemp, cp, realpath } from 'node:fs/promises';
import { createInterface } from 'node:readline';
import { createHash } from 'node:crypto';
import { join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { promisify } from 'node:util';
import { execFile } from 'node:child_process';
import { readRman } from './rman.mjs';
import { offlineArchiveReader } from './global-vfx.mjs';
import { inspectSkn } from './inspect-source.mjs';
import { makeModel, validateModel } from './model.mjs';
import { decodeTexture, encodePng } from './texture.mjs';
import { extractUnitScaleBin } from './unit-scale.mjs';
import { compressAssets } from './compress.mjs';
import { createPrecache } from './merge-manifests.mjs';
import { safeInputPath, safeOutputPath, writeOutputFileAtomic } from './safe-path.mjs';
import { contracts } from './runtime.mjs';
import { contains, ignoredOutput } from './merge-root-output.mjs';
import { argumentsFor } from './plan-fetch.mjs';
const json = v => Buffer.from(JSON.stringify(v, null, 2) + '\n');
const sha = b => createHash('sha256').update(b).digest('hex');
const SOURCE_SHA = 'c080631bd377f60730d979b48807a49f86070517e85b7bafdc32c8666fee7a14';
const PREFIX = 'assets/characters/tft_armorykeycomponent/skins/base/';
export const ANVILS = ['Component', 'Completed'].map((kind, i) => ({
  id: 'TFT_ArmoryKey' + kind, character: 'tft_armorykey' + kind.toLowerCase(),
  mesh: `assets/characters/tft_armorykey${kind.toLowerCase()}/skins/base/armorykey_${i ? 'b' : 'a'}`,
}));

/** Preserve the base's complete manifest/index/UI metadata; replace only these two explicit ids/paths. */
export function mergeAnvilDelta(base, added, payloads) {
  const manifest = structuredClone(base.manifest), ui = structuredClone(base.ui);
  const files = new Map(base.precache.files.map(f => [f.path, f]));
  for (const { id } of ANVILS) {
    const model = added.manifest.models[id], icon = added.ui.assets.find(a => a.kind === 'champion' && a.id === id);
    if (!model || !icon) throw Error('missing-anvil-entry:' + id);
    for (const path of [model.path, icon.path]) {
      if (!/^anvils\/[\w/.-]+$/.test(path) || path.split('/').some(p => p === '..' || p === '.')) throw Error('unsafe-anvil-path');
      const b = payloads.get(path); if (!b) throw Error('missing-anvil-payload:' + path);
      // A delta must never overwrite bytes already referenced by the base's packs.
      const record = { path, bytes: b.length, sha256: sha(b) };
      if (files.has(path) && (files.get(path).sha256 !== record.sha256 || files.get(path).bytes !== record.bytes)) throw Error('base-payload-conflict:' + path);
      files.set(path, record);
    }
    manifest.models[id] = structuredClone(model);
    ui.assets = ui.assets.filter(a => !(a.kind === 'champion' && a.id === id));
    ui.assets.push(structuredClone(icon));
  }
  // v9 indexes ui-assets.json too; its old checksum must not survive the merge.
  const uiBytes = json(ui);
  files.set('ui-assets.json', { bytes: uiBytes.length, sha256: sha(uiBytes) });
  return { manifest, precache: createPrecache(files), ui };
}

export async function buildAnvils({ source = 'assets3d-local/trial/local', base, out = 'assets3d-local/anvil-delta' } = {}) {
  if (!base) throw Error('usage: --base <v9-compatible-root> [--source <cache>] [--out <local-output>]');
  const output = await safeOutputPath(out, { directory: true }), src = resolve(source), baseline = resolve(base);
  await ignoredOutput(output);
  // Reject both ancestor directions, including links: cp must never recurse into its own output.
  for (const input of [src, baseline]) {
    const actual = await realpath(input);
    if (contains(actual, output) || contains(output, actual)) throw Error('output-overlaps-input');
  }
  const input = p => safeInputPath(src, join(src, p)).then(readFile);
  const readBase = p => safeInputPath(baseline, join(baseline, p)).then(readFile);
  const write = (p, b) => writeOutputFileAtomic(join(output, p), b, { force: true });
  const raw = await input('14.24.manifest'); if (sha(raw) !== SOURCE_SHA) throw Error('source-version-mismatch');
  const plan = { wads: [] };
  const reader = offlineArchiveReader({ manifest: readRman(raw), plan, readChunk: id => input(`chunks/${id}.zst`), write });
  const archives = [];
  for (const name of ['DATA/FINAL/TFTCommon.wad.client', 'DATA/FINAL/TFTSet13.wad.client']) archives.push({ name, ...await reader.archive(name) });
  const byHash = new Map();
  for (const a of archives) {
    plan.wads.push({ name: a.name, entries: [] });
    for (const entry of a.index) { const matches = byHash.get(entry.hash) ?? []; matches.push(a.name); byHash.set(entry.hash, matches); }
  }
  for await (const line of createInterface({ input: createReadStream(await safeInputPath(src, join(src, 'hashes/hashes.game.txt'))), crlfDelay: Infinity })) {
    for (const wad of byHash.get(line.slice(0, 16)) ?? []) plan.wads.find(w => w.name === wad).entries.push({ hash: line.slice(0, 16), path: line.slice(17).toLowerCase(), wad });
  }
  const entries = new Map(plan.wads.flatMap(w => w.entries).map(e => [e.path, e])), loaded = new Map();
  async function load(path) {
    if (!loaded.has(path)) { const e = entries.get(path); if (!e) throw Error('missing-source:' + path); loaded.set(path, await reader.extract(e)); }
    return loaded.get(path);
  }
  await mkdir(output, { recursive: true });
  const work = await mkdtemp(join(output, 'build-')), rawRoot = join(work, 'raw'), compressed = join(work, 'compressed');
  const manifest = { schemaVersion: 1, models: {}, effects: {} }, ui = { schemaVersion: 1, patch: '14.24', assets: [] }, reports = [];
  const texture = encodePng(decodeTexture(await load(PREFIX + 'tft7_armorykey.tex')));
  const idle = await load(PREFIX + 'animations/armory_a_idle1.anm');
  for (const spec of ANVILS) {
    const skn = await load(spec.mesh + '.skn'), skl = await load(spec.mesh + '.skl');
    const textures = Object.fromEntries(inspectSkn(skn).submeshes.map(s => [s.name, texture]));
    const result = makeModel(skn, skl, [{ name: 'idle', bytes: idle }], textures);
    if (!validateModel(result.glb).passed) throw Error('invalid-anvil-glb');
    const scale = extractUnitScaleBin(await load(`data/characters/${spec.character}/skins/skin0.bin`), { meshPath: spec.mesh + '.skn' });
    const path = `anvils/models/${spec.id}.glb`;
    await writeOutputFileAtomic(join(rawRoot, path), result.glb);
    manifest.models[spec.id] = { path, animations: { idle: 'idle' }, unitScale: scale.unitScale };
    const iconSource = `assets/characters/${spec.character}/hud/${spec.character}_square.tex`, sourceBytes = await load(iconSource);
    const png = encodePng(decodeTexture(sourceBytes)), iconPath = `anvils/icons/${spec.id}.png`;
    await writeOutputFileAtomic(join(rawRoot, iconPath), png);
    ui.assets.push({ kind: 'champion', id: spec.id, path: iconPath, source: iconSource, bytes: png.length, sha256: sha(png), sourceSha256: sha(sourceBytes) });
    reports.push({ id: spec.id, scale, ...result.report });
  }
  await writeOutputFileAtomic(join(rawRoot, 'manifest.json'), json(manifest));
  await compressAssets({ from: rawRoot, out: compressed });
  const compressedManifest = JSON.parse(await readFile(join(compressed, 'manifest.json'))), payloads = new Map();
  for (const path of [...Object.values(compressedManifest.models).map(m => m.path), ...ui.assets.map(a => a.path)]) payloads.set(path, await readFile(join(compressed, path)));
  const baseBytes = await Promise.all(['manifest.json', 'precache.json', 'ui-assets.json'].map(readBase));
  const [baseManifest, basePrecache, baseUi] = baseBytes.map(b => JSON.parse(b));
  const merged = mergeAnvilDelta({ manifest: baseManifest, precache: basePrecache, ui: baseUi }, { manifest: compressedManifest, ui }, payloads);
  const { assertManifest } = await contracts(); assertManifest(merged.manifest);
  payloads.set('manifest.json', json(merged.manifest)); payloads.set('precache.json', json(merged.precache)); payloads.set('ui-assets.json', json(merged.ui));
  for (const [path, bytes] of payloads) await write('delta/' + path, bytes);
  // A complete local root for browser QA; the archive itself contains only the seven delta files.
  // Repeat runs use a fresh local root; no deletion of arbitrary assets.
  const localRoot = await mkdtemp(join(output, 'root-'));
  await cp(baseline, localRoot, { recursive: true, dereference: true });
  for (const [path, bytes] of payloads) await writeOutputFileAtomic(join(localRoot, path), bytes, { force: true });
  const tar = join(output, 'anvil-assets-delta.tar');
  await safeOutputPath(tar, { force: true });
  await promisify(execFile)('tar', ['--format=ustar', '--sort=name', '--mtime=@0', '--owner=0', '--group=0', '--numeric-owner', '-cf', tar, '-C', join(output, 'delta'), ...[...payloads.keys()].sort()]);
  const report = { ready: true, sourceManifestSha256: SOURCE_SHA, base: Object.fromEntries(['manifest.json', 'precache.json', 'ui-assets.json'].map((p, i) => [p, sha(baseBytes[i])])),
    localRoot, tar, tarBytes: (await readFile(tar)).length, files: [...payloads].map(([path, b]) => ({ path, bytes: b.length, sha256: sha(b) })), models: reports, sources: reader.files };
  await write('report.json', json(report));
  return report;
}
if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const report = await buildAnvils(argumentsFor(process.argv.slice(2), ['--source', '--base', '--out']));
  console.log(JSON.stringify({ ready: report.ready, root: report.localRoot, tar: report.tar, tarBytes: report.tarBytes, files: report.files }));
}
